import { execFileSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

export const bootstrap =
  '# Changelog\n\nRelease entries are assembled from merged PR descriptions. Do not edit this file directly.\n';
export const assemblyPrefix = 'chore: assemble CHANGELOG ';
const categories = new Map([
  ['Added', 1],
  ['Changed', 2],
  ['Deprecated', 1],
  ['Removed', 2],
  ['Fixed', 0],
  ['Security', 0],
]);

export interface ChangelogEntry {
  category: string;
  text: string;
}

export function parseChangelog(body: string): ChangelogEntry[] {
  let active = false;
  let found = false;
  let category: string | undefined;
  let count = 0;
  let fence: string | undefined;
  const entries: ChangelogEntry[] = [];
  for (const line of body.replace(/\r\n/g, '\n').split('\n')) {
    const boundary = line.match(/^\s{0,3}(`{3,}|~{3,})/);
    if (boundary?.[1]) {
      if (!fence) fence = boundary[1];
      else if (boundary[1][0] === fence[0] && boundary[1].length >= fence.length) fence = undefined;
      continue;
    }
    if (fence) continue;
    if (/^#{1,2}\s/.test(line)) {
      if (active && category && count === 0)
        throw new Error(`Empty changelog category: ${category}`);
      active = /^## CHANGELOG\s*$/.test(line);
      if (active && found) throw new Error('Duplicate CHANGELOG section');
      if (active) found = true;
      category = undefined;
      count = 0;
      continue;
    }
    if (!active || !line.trim()) continue;
    // Attribution/metadata blocks end the section, rather than leaking into release notes.
    if (/^(?:>|<!--)/.test(line)) {
      active = false;
      continue;
    }
    if (/^###\s/.test(line)) {
      if (category && count === 0) throw new Error(`Empty changelog category: ${category}`);
      category = line.slice(4).trim();
      if (!categories.has(category)) throw new Error(`Unknown changelog category: ${category}`);
      count = 0;
    } else if (/^-\s+\S/.test(line)) {
      if (!category) throw new Error('Put changelog entries under a ### category');
      entries.push({ category, text: line.slice(2).trim() });
      count++;
    } else if (/^\s+\S/.test(line) && count > 0) {
      const previous = entries.at(-1);
      if (!previous) throw new Error('Missing preceding changelog entry');
      previous.text += ` ${line.trim()}`;
    } else {
      throw new Error('Use category headings and bullet entries in ## CHANGELOG');
    }
  }
  if (category && count === 0) throw new Error(`Empty changelog category: ${category}`);
  if (!found || entries.length === 0)
    throw new Error('PR description needs a nonempty ## CHANGELOG section');
  return entries;
}

export function nextVersion(version: string, entries: ChangelogEntry[]) {
  if (!/^\d+\.\d+\.\d+$/.test(version))
    throw new Error('Expected a stable numeric package version');
  let [major = 0, minor = 0, patch = 0] = version.split('.').map(Number);
  let bump = Math.max(...entries.map((entry) => categories.get(entry.category) ?? Number.NaN));
  if (!Number.isInteger(bump) || bump < 0)
    throw new Error('Cannot version an empty or unknown changelog');
  // Keep the prototype below 1.0 until graduation is deliberate, like the frontend packages.
  if (major === 0 && bump === 2) bump = 1;
  if (bump === 2) {
    major++;
    minor = 0;
    patch = 0;
  } else if (bump === 1) {
    minor++;
    patch = 0;
  } else patch++;
  return `${major}.${minor}.${patch}`;
}

export function renderEntries(entries: ChangelogEntry[]) {
  return [...categories.keys()]
    .flatMap((category) => {
      const group = entries.filter((entry) => entry.category === category);
      return group.length
        ? [`### ${category}`, '', ...group.map((entry) => `- ${entry.text}`), '']
        : [];
    })
    .join('\n')
    .trim();
}

// A squash merge's subject is the PR title. The workflow's startsWith() ignores case, and GitHub
// appends " (#n)", so a title matching the prefix without its trailing space would become one.
export function checkPullRequestTitle(title: string) {
  if (title.toLowerCase().startsWith(assemblyPrefix.trim().toLowerCase()))
    throw new Error(
      `PR titles starting with "${assemblyPrefix.trim()}" are reserved for assembly commits`,
    );
}

export function checkpoint(message: string) {
  if (!message.startsWith(assemblyPrefix)) return undefined;
  return message.match(/^Changelog-Source: ([a-f0-9]{40})$/m)?.[1];
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const eventPath = process.env.GITHUB_EVENT_PATH;
  if (!eventPath) throw new Error('Expected GitHub event path');
  const event = JSON.parse(readFileSync(eventPath, 'utf8')) as {
    pull_request?: { title?: string; body?: string; base: { sha: string } };
  };
  const pr = event.pull_request;
  if (!pr) throw new Error('Changelog gate expects a pull_request event');
  checkPullRequestTitle(pr.title ?? '');
  parseChangelog(pr.body ?? '');
  const base = execFileSync('git', ['merge-base', pr.base.sha, 'HEAD'], {
    encoding: 'utf8',
  }).trim();
  const changed = execFileSync('git', ['diff', '--name-only', base, 'HEAD', '--', 'CHANGELOG.md'], {
    encoding: 'utf8',
  });
  if (changed.trim()) {
    const existed = execFileSync('git', ['ls-tree', '--name-only', base, '--', 'CHANGELOG.md'], {
      encoding: 'utf8',
    });
    if (existed.trim() || readFileSync('CHANGELOG.md', 'utf8') !== bootstrap) {
      throw new Error('Do not edit CHANGELOG.md; update ## CHANGELOG in the PR description');
    }
  }
  console.log('PR-body changelog validated; generated changelog is unchanged');
}
